package ai.inframind.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Component public class JwtService { private final byte[] key; private final long hours; public JwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-hours}") long hours){if(secret.length()<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 characters");this.key=secret.getBytes(StandardCharsets.UTF_8);this.hours=hours;} public String issue(Long id,String email,String role){return Jwts.builder().subject(email).claim("uid",id).claim("role",role).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofHours(hours)))).signWith(Keys.hmacShaKeyFor(key)).compact();} public Claims read(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(token).getPayload();} }
